<?php
declare(strict_types=1);
session_start(); require __DIR__.'/database.php'; $pdo=db(); $token=$_SESSION['cart_token']??'';
$q=$pdo->prepare('SELECT ci.quantity FROM cart_items ci JOIN carts c ON c.id=ci.cart_id WHERE c.token=?');$q->execute([$token]);$items=$q->fetchAll(PDO::FETCH_ASSOC);if(!$items){header('Location:index.php');exit;}
$subtotal=array_sum(array_map(fn($i)=>$i['quantity']*current_price(),$items));$coupon=strtoupper(trim($_POST['coupon']??''));$discount=0;
if($coupon){$s=$pdo->prepare('SELECT * FROM coupons WHERE code=? AND active=1');$s->execute([$coupon]);$c=$s->fetch(PDO::FETCH_ASSOC);if($c)$discount=$c['kind']==='percent'?min($subtotal,(int)round($subtotal*$c['value']/100)):min($subtotal,$c['value']);else $coupon='';}
$error='';
if(isset($_POST['name'])){$name=trim($_POST['name']);$email=strtolower(trim($_POST['email']));$phone=trim($_POST['phone']);$password=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8)$error='Informe nome, e-mail e uma senha de pelo menos 8 caracteres.';else{$pdo->prepare('INSERT INTO customers(name,email,phone,password_hash)VALUES(?,?,?,?) ON CONFLICT(email)DO UPDATE SET name=excluded.name,phone=excluded.phone,password_hash=excluded.password_hash')->execute([$name,$email,$phone,password_hash($password,PASSWORD_DEFAULT)]);$s=$pdo->prepare('SELECT id FROM customers WHERE email=?');$s->execute([$email]);$customer=(int)$s->fetchColumn();$s=$pdo->prepare('SELECT id FROM carts WHERE token=?');$s->execute([$token]);$cart=(int)$s->fetchColumn();$total=$subtotal-$discount;$nsu='406-'.date('YmdHis').'-'.bin2hex(random_bytes(3));$pdo->prepare('INSERT INTO orders(order_nsu,customer_id,cart_id,subtotal_cents,discount_cents,total_cents,coupon_code)VALUES(?,?,?,?,?,?,?)')->execute([$nsu,$customer,$cart,$subtotal,$discount,$total,$coupon?:null]);$cfg=is_file(__DIR__.'/config.php')?require __DIR__.'/config.php':[];$handle=$cfg['infinitepay_handle']??'';if(!$handle)$error='Pedido registrado. Configure a InfinitePay em config.php para gerar o Pix.';else{$payload=['handle'=>$handle,'order_nsu'=>$nsu,'items'=>[['quantity'=>1,'price'=>$total,'description'=>setting('product_name')]],'redirect_url'=>$cfg['redirect_url']??'','webhook_url'=>$cfg['webhook_url']??''];$ch=curl_init('https://api.checkout.infinitepay.io/links');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_POSTFIELDS=>json_encode($payload),CURLOPT_RETURNTRANSFER=>true]);$data=json_decode((string)curl_exec($ch),true);curl_close($ch);if(!empty($data['url'])){$pdo->prepare('UPDATE orders SET gateway_url=? WHERE order_nsu=?')->execute([$data['url'],$nsu]);header('Location:'.$data['url']);exit;}$error='Erro ao iniciar pagamento. Revise a configuração da InfinitePay.';}}}
?><!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Finalizar compra — 406</title><style>body{margin:0;background:#0b0908;color:#eee;font-family:Arial}main{width:min(600px,90vw);margin:70px auto}form{display:grid;gap:13px}input,button{padding:14px;background:#18120f;border:1px solid #53433b;color:#fff}button{background:#b71922;border:0;font-weight:bold}.err{color:#ffaaa5}a{color:#fff}</style><main><a href="cart.php">← carrinho</a><h1>FINALIZAR COMPRA</h1><p>Total: <strong><?=money($subtotal-$discount)?></strong></p><form method="post"><input name="coupon" placeholder="Cupom (opcional)" value="<?=htmlspecialchars($coupon)?>"><input name="name" placeholder="Nome completo" required><input type="email" name="email" placeholder="E-mail" required><input name="phone" placeholder="Telefone"><input name="password" type="password" minlength="8" placeholder="Crie uma senha (mínimo 8 caracteres)" required><button>GERAR PAGAMENTO PIX</button><p class="err"><?=htmlspecialchars($error)?></p></form></main></html>